//! `T083` — grammar ABI check.
//!
//! The grammar crates were generated by tree-sitter CLIs spanning **0.23–0.25**;
//! our runtime is **0.26** (`SPIKES.md`, "Grammars — the first-class twelve").
//! tree-sitter versions its language ABI and is backwards- but *not*
//! forwards-compatible, so a grammar generated by a newer CLI than the runtime
//! is a hard load failure and a grammar older than
//! `MIN_COMPATIBLE_LANGUAGE_VERSION` is the same. This test loads every grammar
//! we ship against the real 0.26 runtime and parses a fixture with each.
//!
//! The bar is **no `ERROR` and no `MISSING` node anywhere in the tree**, not
//! "`parse()` returned `Some`". tree-sitter's whole point is that it recovers
//! from anything, so a returned tree proves nothing on its own.
//!
//! `T037` (`define-language` + the twelve declarations, S4) assumes this passed.
//! The write-up is `GRAMMAR-ABI.md`, next to this file.

// The verdict table this test prints *is* the deliverable — `GRAMMAR-ABI.md` is
// transcribed from it. `print_stdout` is denied workspace-wide because a stray
// print corrupts the TUI frame; a test binary owns its own stdout.
#![allow(clippy::print_stdout)]

use tree_sitter::{Language, Node, Parser};

/// The first-class twelve minus CSV, which `T082` implements by hand.
const EXPECTED_GRAMMAR_COUNT: usize = 11;

/// One row of the verdict table.
struct Grammar {
    /// The name `define-language` will use in `runtime/` (`T037`).
    language: &'static str,
    /// Crate and version, as pinned in `SPIKES.md`'s manifest.
    krate: &'static str,
    /// Fixture path, relative to this file.
    fixture: &'static str,
    /// The fixture's bytes.
    source: &'static str,
    /// The grammar, resolved through `LanguageFn::into()`.
    load: fn() -> Language,
    /// Constructs this grammar gets wrong that the fixture therefore avoids.
    /// Every entry has a matching characterisation test below asserting the gap
    /// is still there — so the workaround cannot outlive the bug silently, and
    /// the verdict table cannot go green on a shrinking fixture.
    known_gaps: &'static [&'static str],
}

impl std::fmt::Debug for Grammar {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Grammar")
            .field("language", &self.language)
            .field("krate", &self.krate)
            .field("fixture", &self.fixture)
            .finish_non_exhaustive()
    }
}

